import json
bl=np.load('base_logits.npy'); ids=json.load(open('all_ids.json'))
def stress(lg, ks=(1,1.5,2,3)):
    pb=bl.argmax(1); d=lg-bl
    return [int(((bl/k+d).argmax(1)!=pb).sum()) for k in ks]
for p in ['pass_10','pass_11','pass_12']:
    m=json.load(open(p+'/meta.json')); lg=np.load(p+'/logits.npy')
    print(p, lg.shape, {k:m[k] for k in m if k not in ('ids',)} if len(str(m))<600 else list(m.keys()))
    if lg.shape[0]==1000:
        mid=m.get('ids'); 
        if mid and mid!=ids: lg=lg[[mid.index(i) for i in ids]]
        print(' stress',stress(lg), np.sqrt(((lg-bl)**2).mean()).round(4))
